{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "In young healthy subjects, the bioavailability of S-9780 after oral 8 mg perindopril was 19% ± 7%, a point estimate below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Absolute oral bioavailability of oxybutynin was 6.2 (1.2)% in volunteers receiving a 5 mg tablet, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Absolute oral bioavailability of β-sitosterol was 0.41% in healthy humans after oral versus intravenous administration, far below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence supports low absolute oral bioavailability; multiple absolute human studies report values well below 20% (e.g., 6.2%, 3.3%, 0.41%), with only isolated altered-condition or outlier values above threshold.",
  "evidence_gaps": [
    "Molecule 1 has a near-threshold value of 19% ± 7% and a 30% value from cirrhotic patients, adding some uncertainty.",
    "Several records are qualitative (e.g., 'poor', 'extremely low') rather than numeric absolute measurements.",
    "Molecule 7 includes a drospirenone record that appears to be a different compound and was discounted as a provenance conflict."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

